package servicio;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.math.BigDecimal;import java.time.*;import org.junit.jupiter.api.Test;import dao.OrdenPagoDAO;import negocio.*;
class CreacionOrdenPagoClienteServiceTest {@Test void reutilizaOrdenPorIdempotencia(){OrdenPagoDAO dao=mock(OrdenPagoDAO.class);PagoService pagos=mock(PagoService.class);when(pagos.totalAcreditado(7)).thenReturn(BigDecimal.ZERO);OrdenPago previa=new OrdenPago();previa.setId(22);when(dao.buscarPorIdempotencia("reserva:7:senia:6250.00:manual")).thenReturn(previa);var s=new CreacionOrdenPagoClienteService(dao,pagos,new OrdenPagoService(),Clock.systemUTC());assertSame(previa,s.crearManual(7,new BigDecimal("6250"),LocalDateTime.now().plusMinutes(10)));verify(dao,never()).guardar(any());}@Test void importeSeCalculaEnServidor(){OrdenPagoDAO dao=mock(OrdenPagoDAO.class);PagoService pagos=mock(PagoService.class);when(pagos.totalAcreditado(7)).thenReturn(new BigDecimal("1250"));when(dao.guardar(any())).thenAnswer(i->i.getArgument(0));var s=new CreacionOrdenPagoClienteService(dao,pagos,new OrdenPagoService(),Clock.systemUTC());OrdenPago o=s.crearManual(7,new BigDecimal("6250"),LocalDateTime.now().plusMinutes(10));assertEquals(new BigDecimal("5000.00"),o.getImporte());assertEquals(EstadoOrdenPago.ESPERANDO_VERIFICACION,o.getEstado());}}
